const fs=require("fs");
const p=require("./palette.json");
const ids=new Set([...Object.values(p.roles).flat(),...p.objects]);
const src=fs.readFileSync("vocab/base.mjs","utf8");
const lines=src.split("\n");
const vals=[...src.matchAll(/export const \w+ = "([^"]+)";/g)].map(m=>m[1]);
const palVals=vals.filter(v=>ids.has(v));
const notPal=vals.filter(v=>!ids.has(v) && !/^\d/.test(v));
console.log("palette consts", palVals.length, "unique", new Set(palVals).size, "ids", ids.size);
console.log("missing consts for ids:", [...ids].filter(i=>!palVals.includes(i)));
console.log("non-palette string consts (sites):", notPal.length? notPal:"none");
// every export preceded by comment or with trailing comment
const bad=[];
lines.forEach((l,i)=>{ if(/^export /.test(l)){ const prev=lines[i-1]||""; if(!/^\s*\/\//.test(prev) && !/\/\/ /.test(l) && !/^\s*\/\*\*.*\*\/\s*$/.test(prev)) bad.push(i+1+": "+l.slice(0,60)); }});
console.log("undocumented exports:", bad.length? bad : "none");
' && node --input-type=module -e '
import("/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/midcentury-crew4/vocab/base.mjs").then(m=>{
 const a=m.rng(7), b=m.rng(7), c=m.rng(8);
 const xs=[...Array(5)].map(()=>a()), ys=[...Array(5)].map(()=>b());
 console.log("same seed equal:", xs.every((v,i)=>v===ys[i]), "diff seed differs:", c()!==xs[0]);
 console.log("in [0,1):", xs.every(v=>v>=0&&v<1));
 console.log("exports:", Object.keys(m).length, m.GRID_SIZE, m.BEAM_LINES.join(","), m.DIRT);
});'

