input.command:
node -e '
const fs=require("fs");
const p=require("./palette.json");
const ids=new Set([...Object.values(p.roles).flat(),...p.objects]);
const lines=fs.readFileSync("plan.md","utf8").split("\n");
const s=lines.findIndex(l=>l.startsWith("## PALETTE")), e=lines.findIndex(l=>l.startsWith("## VOCABULARY"));
const toks=new Set(lines.slice(s,e).join("\n").match(/\b[a-z]+(?:_[a-z]+)+\b/g));
const miss=[...toks].filter(t=>!ids.has(t));
console.log("plan palette tokens not in palette.json:", miss.join(" "));
const ids2=[...ids].filter(i=>!toks.has(i)); console.log("palette ids not named in plan palette section:", ids2.join(" "));
'

